iterations.reply:
Two notes on the choices below:

- `RunInfo` has no text field, so I used `info.date` as the `q` value, percent-encoded.
- The enrichment call uses `fetch` and discards its result, so a transport failure can't change the output. The output depends only on the `subscriptions` store.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment record: fetched on every call, result deliberately unused
        // so the node's output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let urls = match state_read::get("subscriptions") {
            Some(raw) => raw
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

